// Keep normal expected value at .05 per kill. Rank promotion must not inflate
// the floor economy: special encounters share the remaining value in proportion
// to their rank's elite/Boss reward weight (not stale archetype override credit).
const SPECIAL_SCALES = UNITS.map((units, i) =>
  (TARGETS[i] - units.filter(u => u.role === 'normal').length * .05)
  / units.filter(u => u.role !== 'normal').reduce((sum, u) => sum + oldCredit(u), 0))
const TARGET_COUNTS = UNITS.map((units, i) => units.reduce((sum, u) =>
  sum + oldCredit(u) * (u.role === 'normal' ? 1 : SPECIAL_SCALES[i]) / CORE_RANK_VALUES[u.rank], 0))

export const CORE_DROP_RULES = Object.freeze(Object.fromEntries(UNITS.map((units, index) => {
  const targetValue = TARGETS[index], row = CALIBRATED[index], expectedCount = TARGET_COUNTS[index]
  const chancesByRole = Object.freeze(Object.fromEntries(
    ['normal', 'elite', 'boss'].map(role => [role, Object.freeze(row[role])]),
  ))
  const summaryChance = role => {
    const group = units.filter(u => u.role === role)
    return group.reduce((sum, u) => sum + chancesByRole[role][u.rank], 0) / group.length
  }
  const minValue = Math.ceil(targetValue * .9), maxValue = Math.floor(targetValue * 1.1)
  let minimumPhysicalCount = 0, maximumValue = 0
  const descending = units.map(u => CORE_RANK_VALUES[u.rank]).sort((a, b) => b - a)
  while (maximumValue < minValue) maximumValue += descending[minimumPhysicalCount++]
  const minCount = Math.max(1, minimumPhysicalCount, Math.floor(expectedCount * .5))
  return [index + 1, Object.freeze({
    floor: index + 1,
    minCount, maxCount: Math.max(minCount + 2, Math.ceil(expectedCount * 1.5)),
    minValue, maxValue, chancesByRole,
    // Count-weighted display summaries only; sampling uses the indexed arrays.
    normalChance: summaryChance('normal'), eliteChance: summaryChance('elite'),
    bossChance: summaryChance('boss'), targetValue,
  })]
})))

const GROUPS = UNITS.map((units, floorIndex) => {
  const groups = []
  units.forEach((u, index) => {
    let group = groups.find(g => g.role === u.role && g.rank === u.rank)
    if (!group) {
      const chance = CORE_DROP_RULES[floorIndex + 1].chancesByRole[u.role][u.rank]
      if (!(chance > 0 && chance < 1)) throw new Error('Uncalibrated tower loot archetype')
      group = { role: u.role, rank: u.rank, value: CORE_RANK_VALUES[u.rank],
        logMiss: Math.log1p(-chance), indices: [] }
      groups.push(group)
    }
    group.indices.push(index)
  })
  return groups
})

// At most one recent immutable result and one eight-number fallback recipe per
// floor. No seed-keyed history; evicting either never changes future results.
const recent = Array(9).fill(null)
const recipes = Array(9).fill(null)

function lootRandom(floor, seed) {
  // Domain separation plus avalanche: seed 0 is valid, not a default sentinel.
  let state = (seed ^ Math.imul(floor, 0x9e3779b9) ^ 0x434f5245) >>> 0
  state = Math.imul(state ^ (state >>> 16), 0x85ebca6b)
  state = Math.imul(state ^ (state >>> 13), 0xc2b2ae35)
  state = (state ^ (state >>> 16)) >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = Math.imul(state ^ (state >>> 15), state | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 0x100000000
  }
}

function fallbackRecipe(floor) {
  if (recipes[floor - 1]) return recipes[floor - 1]
  const units = UNITS[floor - 1], rule = CORE_DROP_RULES[floor]
  const count = rule.maxCount, value = rule.maxValue, width = value + 1
  const available = Array(8).fill(0), blocks = []
  for (const u of units) available[u.rank]++
  // Binary blocks represent every feasible quantity 0..available for each rank.
  // This bounded knapsack runs only once per floor, not once per seed.
  for (let rank = 1; rank <= 7; rank++) {
    const denomination = CORE_RANK_VALUES[rank]
    let remaining = Math.min(available[rank], count, Math.floor(value / denomination))
    for (let size = 1; remaining > 0; size *= 2) {
      const quantity = Math.min(size, remaining)
      blocks.push({ rank, quantity, value: denomination * quantity })
      remaining -= quantity
    }
  }
  const parent = new Int16Array((count + 1) * width).fill(-1)
  parent[0] = -2
  blocks.forEach((block, index) => {
    for (let c = count; c >= block.quantity; c--) {
      for (let v = value; v >= block.value; v--) {
        const at = c * width + v, previous = (c - block.quantity) * width + v - block.value
        if (parent[at] === -1 && parent[previous] !== -1) parent[at] = index
      }
    }
  })
  // Denominations have gaps: floor nine's 119 target is not representable.
  // Choose the feasible value nearest target, then count nearest old-credit
  // expected count. Both dimensions stay inside the published budget.
  let chosenCount = -1, chosenValue = -1, bestValueDistance = Infinity, bestCountDistance = Infinity
  for (let v = rule.minValue; v <= value; v++) {
    for (let c = rule.minCount; c <= count; c++) {
      if (parent[c * width + v] === -1) continue
      const dv = Math.abs(v - rule.targetValue), dc = Math.abs(c - TARGET_COUNTS[floor - 1])
      if (dv < bestValueDistance || dv === bestValueDistance && dc < bestCountDistance) {
        chosenCount = c; chosenValue = v; bestValueDistance = dv; bestCountDistance = dc
      }
    }
  }
  if (chosenCount < 0) throw new Error(`Infeasible core budget: floor ${floor}`)
  const recipe = Array(8).fill(0)
  for (let c = chosenCount, v = chosenValue; c > 0;) {
    const block = blocks[parent[c * width + v]]
    recipe[block.rank] += block.quantity
    c -= block.quantity
    v -= block.value
  }
  recipes[floor - 1] = Object.freeze(recipe)
  return recipes[floor - 1]
}

function fallback(floor, random) {
  const recipe = fallbackRecipe(floor), pools = Array.from({ length: 8 }, () => [])
  for (const unit of UNITS[floor - 1]) pools[unit.rank].push(unit)
  const selected = new Set()
  for (let rank = 1; rank <= 7; rank++) {
    const pool = pools[rank]
    // Partial Fisher-Yates chooses distinct authored units of exactly this rank.
    for (let i = 0; i < recipe[rank]; i++) {
      const j = i + Math.floor(random() * (pool.length - i))
      ;[pool[i], pool[j]] = [pool[j], pool[i]]
      selected.add(pool[i].key)
    }
  }
  return Object.fromEntries(UNITS[floor - 1].filter(u => selected.has(u.key)).map(u => [u.key, u.rank]))
}

/**
 * Return a frozen drop-only {"wave:localId": rank} object for floor 1..9 and
 * uint32 seed. The caller must persist the ORIGINAL seed and credit actual kills
 * only; partial runs are never topped up to these full-floor bounds.
 */
export function buildCoreDropPlan(floor, seed) {
  if (!Number.isInteger(floor) || floor < 1 || floor > 9
    || !Number.isInteger(seed) || seed < 0 || seed > 0xffffffff) {
    throw new RangeError('Invalid tower loot floor or seed')
  }
  if (recent[floor - 1]?.seed === seed) return recent[floor - 1].plan
  const units = UNITS[floor - 1], rule = CORE_DROP_RULES[floor]
  const random = lootRandom(floor, seed)
  let result
  for (let attempt = 0; attempt < MAX_PROPOSALS; attempt++) {
    const selected = []
    let value = 0
    // Geometric failure runs are exactly Bernoulli sampling within equal-rate
    // groups. This avoids hundreds of RNG calls for rare high-value drops.
    for (const group of GROUPS[floor - 1]) {
      let cursor = 0
      while (cursor < group.indices.length) {
        cursor += Math.floor(Math.log1p(-random()) / group.logMiss)
        if (cursor >= group.indices.length) break
        selected.push(group.indices[cursor++])
        value += group.value
      }
    }
    const count = selected.length
    if (count >= rule.minCount && count <= rule.maxCount
      && value >= rule.minValue && value <= rule.maxValue) {
      result = Object.fromEntries(selected.sort((a, b) => a - b)
        .map(index => [units[index].key, units[index].rank]))
      break
    }
  }
  const plan = Object.freeze(result ?? fallback(floor, random))
  recent[floor - 1] = { seed, plan }
  return plan
}
